content.content:
/* Form */

.form .btn {
  min-width: 140px;
}

.form-field {
  margin-bottom: 0;
}

.form-label {
  display: block;
  margin-bottom: var(--space-1);
  font-size: 14px;
  font-weight: 600;
}

.form-input {
  display: block;
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-md);
  background: var(--color-surface);
  font: inherit;
  font-size: 15px;
  color: var(--color-ink);
}

textarea.form-input {
  min-height: 120px;
  resize: vertical;
}

.form-input:focus {
  outline: 2px solid var(--color-brand);
  outline-offset: 1px;
}

.form-input.is-invalid {
  border-color: var(--color-danger);
}

.form-error {
  margin-top: var(--space-1);
  font-size: 13px;
  color: var(--color-danger);
}

.form-check {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  font-size: 14px;
}

.form-check input {
  margin: 3px 0 0;
}

.form-inline {
  display: flex;
  gap: var(--space-2);
}

.form-inline .form-input {
  flex: 1;
  min-width: 0;
}

/* Table */

.table-wrap {
  overflow-x: auto;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-lg);
  background: var(--color-surface);
}

.table {
  width: 100%;
